// The languages and themes code scenes highlight in the page (JavaScript regex engine, no WASM).
// A language not listed here falls back to plain text.
import { createHighlighterCore } from 'shiki/core'
import { createJavaScriptRegexEngine } from 'shiki/engine/javascript'
import dark from '@shikijs/themes/github-dark-default'
import light from '@shikijs/themes/github-light'
import l0 from '@shikijs/langs/javascript'
import l1 from '@shikijs/langs/typescript'
import l2 from '@shikijs/langs/tsx'
import l3 from '@shikijs/langs/jsx'
import l4 from '@shikijs/langs/json'
import l5 from '@shikijs/langs/jsonc'
import l6 from '@shikijs/langs/yaml'
import l7 from '@shikijs/langs/toml'
import l8 from '@shikijs/langs/python'
import l9 from '@shikijs/langs/rust'
import l10 from '@shikijs/langs/go'
import l11 from '@shikijs/langs/bash'
import l12 from '@shikijs/langs/shellscript'
import l13 from '@shikijs/langs/html'
import l14 from '@shikijs/langs/css'
import l15 from '@shikijs/langs/vue'
import l16 from '@shikijs/langs/markdown'
import l17 from '@shikijs/langs/sql'
import l18 from '@shikijs/langs/dockerfile'
import l19 from '@shikijs/langs/diff'
import l20 from '@shikijs/langs/c'
import l21 from '@shikijs/langs/cpp'
import l22 from '@shikijs/langs/java'
import l23 from '@shikijs/langs/csharp'
import l24 from '@shikijs/langs/ruby'
import l25 from '@shikijs/langs/php'
import l26 from '@shikijs/langs/lua'
import l27 from '@shikijs/langs/ini'
import l28 from '@shikijs/langs/xml'
import l29 from '@shikijs/langs/svelte'
import l30 from '@shikijs/langs/kotlin'
import l31 from '@shikijs/langs/swift'
import l32 from '@shikijs/langs/zig'
import l33 from '@shikijs/langs/nix'
import l34 from '@shikijs/langs/hcl'
import l35 from '@shikijs/langs/powershell'
const langs = [l0,l1,l2,l3,l4,l5,l6,l7,l8,l9,l10,l11,l12,l13,l14,l15,l16,l17,l18,l19,l20,l21,l22,l23,l24,l25,l26,l27,l28,l29,l30,l31,l32,l33,l34,l35,]
let hl
export async function codeToTokens(code, { lang, theme }) {
  hl ||= await createHighlighterCore({ themes: [dark, light], langs, engine: createJavaScriptRegexEngine() })
  if (!hl.getLoadedLanguages().includes(lang)) lang = 'text'
  return hl.codeToTokens(code, { lang, theme })
}
